import { FiSearch } from "react-icons/fi";
import { categories, allColors } from "../data/products";

/**
 * FilterSidebar Component
 * Shop filtering sidebar for categories, colors, sizes, price range, and search
 *
 * @param {object} filters - Current filter state
 * @param {function} setFilters - Filter state setter
 * @param {function} onApply - Apply filters callback
 */
export default function FilterSidebar({ filters, setFilters, onApply }) {
  const sizes = ["S", "M", "L", "XL"];

  const handleCategoryToggle = (category) => {
    setFilters((prev) => {
      const current = [...prev.categories];
      if (category === "All Products") {
        return { ...prev, categories: current.includes("All Products") ? [] : ["All Products"] };
      }
      const filtered = current.filter((c) => c !== "All Products");
      const idx = filtered.indexOf(category);
      if (idx >= 0) {
        filtered.splice(idx, 1);
      } else {
        filtered.push(category);
      }
      return { ...prev, categories: filtered.length === 0 ? ["All Products"] : filtered };
    });
  };

  const handleColorToggle = (colorHex) => {
    setFilters((prev) => {
      const current = [...prev.colors];
      const idx = current.indexOf(colorHex);
      if (idx >= 0) {
        current.splice(idx, 1);
      } else {
        current.push(colorHex);
      }
      return { ...prev, colors: current };
    });
  };

  const handleSizeToggle = (size) => {
    setFilters((prev) => {
      const current = [...prev.sizes];
      const idx = current.indexOf(size);
      if (idx >= 0) {
        current.splice(idx, 1);
      } else {
        current.push(size);
      }
      return { ...prev, sizes: current };
    });
  };

  const handlePriceChange = (type, value) => {
    setFilters((prev) => ({
      ...prev,
      priceRange: { ...prev.priceRange, [type]: value ? Number(value) : null },
    }));
  };

  const clearFilters = () => {
    setFilters({
      search: "",
      categories: ["All Products"],
      colors: [],
      sizes: [],
      priceRange: { min: null, max: null },
    });
  };

  return (
    <aside className="w-full md:w-1/5 shrink-0">
      <div className="sticky top-32 bg-cream p-6 rounded-xl shadow-ambient gold-hairline">
        {/* Search */}
        <div className="mb-8">
          <h3 className="font-display text-headline-md text-burgundy mb-4 text-[20px]">
            Refine Search
          </h3>
          <div className="relative">
            <input
              className="w-full bg-transparent border-b border-gold/40 py-2 focus:ring-0 focus:border-burgundy transition-colors font-body text-body-md outline-none"
              placeholder="Search products..."
              type="text"
              value={filters.search}
              onChange={(e) => setFilters((prev) => ({ ...prev, search: e.target.value }))}
            />
            <FiSearch className="absolute right-0 top-3 text-burgundy/60" size={16} />
          </div>
        </div>

        {/* Categories */}
        <div className="mb-8">
          <h4 className="font-body text-label-lg uppercase text-burgundy mb-4 text-[12px]">
            Categories
          </h4>
          <div className="space-y-2">
            {categories.map((cat) => (
              <label key={cat} className="flex items-center gap-3 cursor-pointer group">
                <input
                  type="checkbox"
                  className="rounded-sm border-gold/40 text-burgundy focus:ring-burgundy"
                  checked={filters.categories.includes(cat)}
                  onChange={() => handleCategoryToggle(cat)}
                />
                <span className="font-body text-body-md group-hover:text-burgundy transition-colors">
                  {cat}
                </span>
              </label>
            ))}
          </div>
        </div>

        {/* Colors */}
        <div className="mb-8">
          <h4 className="font-body text-label-lg uppercase text-burgundy mb-4 text-[12px]">
            Colors
          </h4>
          <div className="flex flex-wrap gap-2">
            {allColors.map((color) => (
              <button
                key={color.hex}
                className={`w-6 h-6 rounded-full transition-all ${
                  filters.colors.includes(color.hex)
                    ? "ring-2 ring-offset-2 ring-burgundy"
                    : "border border-gold/20 hover:ring-2 hover:ring-gold"
                }`}
                style={{ backgroundColor: color.hex }}
                title={color.name}
                onClick={() => handleColorToggle(color.hex)}
              />
            ))}
          </div>
        </div>

        {/* Sizes */}
        <div className="mb-8">
          <h4 className="font-body text-label-lg uppercase text-burgundy mb-4 text-[12px]">
            Sizes
          </h4>
          <div className="grid grid-cols-2 gap-2">
            {sizes.map((size) => (
              <button
                key={size}
                className={`py-2 px-3 border font-body text-body-md transition-all ${
                  filters.sizes.includes(size)
                    ? "bg-burgundy text-white border-burgundy"
                    : "border-gold/40 hover:bg-burgundy hover:text-white"
                }`}
                onClick={() => handleSizeToggle(size)}
              >
                {size}
              </button>
            ))}
          </div>
        </div>

        {/* Price Range */}
        <div className="mb-8">
          <h4 className="font-body text-label-lg uppercase text-burgundy mb-4 text-[12px]">
            Price Range
          </h4>
          <div className="flex gap-2 items-center">
            <input
              type="number"
              placeholder="Min"
              className="w-full bg-transparent border-b border-gold/40 py-2 focus:ring-0 focus:border-burgundy transition-colors font-body text-body-md outline-none text-sm"
              value={filters.priceRange.min || ""}
              onChange={(e) => handlePriceChange("min", e.target.value)}
            />
            <span className="text-on-surface-variant">-</span>
            <input
              type="number"
              placeholder="Max"
              className="w-full bg-transparent border-b border-gold/40 py-2 focus:ring-0 focus:border-burgundy transition-colors font-body text-body-md outline-none text-sm"
              value={filters.priceRange.max || ""}
              onChange={(e) => handlePriceChange("max", e.target.value)}
            />
          </div>
        </div>

        {/* Apply / Clear */}
        <div className="space-y-3">
          <button
            onClick={onApply}
            className="w-full py-4 bg-burgundy text-white font-body text-label-lg uppercase tracking-widest hover:bg-primary-container transition-all shadow-ambient"
          >
            Apply Filters
          </button>
          <button
            onClick={clearFilters}
            className="w-full py-2 text-on-surface-variant font-body text-label-sm uppercase tracking-widest hover:text-primary transition-all"
          >
            Clear All
          </button>
        </div>
      </div>
    </aside>
  );
}
